{
  "diagnosis": "Recurring failures come from matching the patient's chief symptom or a single stated indication to a drug class while ignoring (a) the patient's other stated diagnoses/risk states, (b) prior adverse reactions or contraindications, (c) combination purposes explicitly implied by the doctor's stated treatment goals, and (d) whether two options are near-equivalent agents where the standard/preferred member or the one not requiring an unstated fact should be chosen. The agent also over-weights 'most obvious' symptom-specific options and under-weights safety and diagnostic-context facts (e.g., current medications, prior ptosis, NSAID use, family history, renal involvement).",
  "skills": [
    {
      "id": "chief_complaint_vs_stated_condition",
      "text": "Before choosing, extract the final diagnosis or suspected condition from the dialogue, not just the presenting symptom. Select the option indicated for the stated/suspected condition; reject options that only match a symptom or an unrelated organ system."
    },
    {
      "id": "conditional_contraindication_check",
      "text": "If the patient states a prior adverse reaction, intolerance, or condition that is a known class contraindication, exclude all options in that class unless the dialogue explicitly resolves the contraindication. Do not assume a class risk is absent because it is not restated."
    },
    {
      "id": "goal_composite_matching",
      "text": "When the doctor states two or more treatment goals in the same utterance (e.g., prevent thrombotic events AND reduce NSAID ulcer risk), prefer the option whose mechanism or combination covers both goals; do not choose an option that covers only one goal."
    },
    {
      "id": "equivalent_agents_prefer_standard_or_safer",
      "text": "If two options are near-equivalent members of the same class or are the same molecule, prefer the one that is the standard/preferred formulation for the stated indication or the one that does not require an unstated patient fact. Do not choose an option solely because it is listed first or last."
    },
    {
      "id": "current_medication_context",
      "text": "Treat the patient's current medication as clinically relevant to the suspected condition and to safety. Consider whether the current drug is a diagnostic agent, a treatment for the suspected condition, or a potential contributor to symptoms; use that context to narrow options rather than ignoring it."
    },
    {
      "id": "renal_and_family_history_flags",
      "text": "If the dialogue states renal involvement (decreased urine output, kidney scarring, proteinuria) or a family history consistent with a named genetic syndrome, prefer options indicated to slow progression of that syndrome's organ damage and avoid options that are unrelated or contraindicated in renal impairment."
    },
    {
      "id": "antibiotic_spectrum_matching",
      "text": "For suspected intra-abdominal or peritoneal infection, match the option's spectrum to the stated site and organisms; do not select an antibiotic with incomplete anaerobic or gram-negative coverage when the diagnosis is peritonitis or another intra-abdominal infection."
    }
  ],
  "focus_terms": [
    "current medication",
    "started taking",
    "prior adverse reaction",
    "drooping eyelids",
    "ptosis",
    "NSAID",
    "gastric ulcer",
    "kidney problems",
    "scarring on my kidneys",
    "urine output has decreased",
    "family medical history",
    "bloody diarrhea",
    "suspected hemolytic-uremic syndrome",
    "peritonitis",
    "intra-abdominal infection",
    "vitamin D deficiency",
    "musculoskeletal pain",
    "arterial thrombotic event"
  ],
  "modules": {
    "patient_evidence": "Extract: stated/suspected diagnosis; all current medicines and why they are taken; prior adverse drug reactions or intolerances; family history; renal, hepatic, cardiac, or bleeding risk facts; and any two-part treatment goal stated by the doctor. Treat these as active constraints, not background.",
    "safety_check": "Screen every option against stated contraindications and interactions. If the patient reports a prior class-specific adverse reaction, exclude that class unless the dialogue explicitly says it is safe. Do not infer absent facts as normal; if a required fact is missing, do not assume it is present.",
    "option_selection": "Rank options by: (1) indication for the stated/suspected diagnosis, (2) coverage of all stated treatment goals, (3) absence of patient-specific contraindications, (4) standard/preferred choice among near-equivalent options. Choose the highest-ranked option; do not default to the most symptom-obvious drug."
  }
}

{
  "diagnosis": "Recurring failures come from four sources: (1) indication matching stops at the surface diagnosis and misses the clinical qualifier that selects within a drug class (acute vs prophylactic, first-line vs advanced, replacement vs activated vitamin D, chronic vs procedural use); (2) answer choices are compared by general drug familiarity rather than by the specific severity, timing, and setting stated in the dialogue; (3) safety reasoning treats a drug class as uniformly contraindicated and over-avoids effective options when only a subset of the class carries the risk; (4) the single most decision-changing patient fact is present in the dialogue but not surfaced as an exact excerpt, so it is not weighed. Prior skills are absent, so nothing useful needs preserving; the old option_selection generalized \"best satisfies indication and safety\" without operationalizing clinical qualifiers, and that unsupported generalization is replaced.",
  "skills": [
    {
      "id": "extract_qualifying_clinical_modifier",
      "text": "For every diagnosis, extract at least one qualifier beyond the disease name: severity, acuity, timing (acute vs chronic vs breakthrough), prior therapy failure, age group, pregnancy, organ function, vaccination status, or an explicit doctor statement that one option would be preferable. Use that qualifier as the primary discriminator among same-class options."
    },
    {
      "id": "temporal_and_line_of_therapy_match",
      "text": "Match drug indication to the time course and line of therapy stated in the dialogue. Prophylaxis drugs are not interchangeable with acute/rescue drugs, and first-line or replacement therapies are not interchangeable with later-line, second-line, or activated therapies unless the dialogue specifies the later-line scenario."
    },
    {
      "id": "severity_and_setting_match",
      "text": "Match the option's labeled use setting to the dialogue's setting. Reject options whose labeled use is procedural sedation, hospital-only, rescue-only, or acute crisis management when the encounter describes routine outpatient chronic management, and reject routine outpatient options when the dialogue describes an acute crisis."
    },
    {
      "id": "class_subset_safety_precision",
      "text": "When a drug class is mentioned as risky, name the subclass or property carrying the risk rather than avoiding the entire class. Beta-blockers are not uniformly contraindicated in vasospastic conditions; non-selective beta-blockers carry more peripheral vasoconstriction risk than cardioselective beta-blockers, so do not exclude a cardioselective beta-blocker merely because of a vasospastic diagnosis."
    },
    {
      "id": "explicit_doctor_preference_as_selector",
      "text": "If the doctor states or implies that one option is preferred, safer, or necessary given a patient fact, treat that statement as the decisive comparator over general class familiarity. Combine it with the labeled indication before selecting."
    },
    {
      "id": "activation_and_replacement_distinction",
      "text": "Distinguish replacement forms from activated or hydroxylated forms. When the dialogue describes a nutritional deficiency state without renal failure or hypoparathyroidism, prefer the replacement form over the activated form unless the dialogue explicitly states renal impairment or a condition requiring activated vitamin D."
    }
  ],
  "focus_terms": [
    "breakthrough attacks",
    "severe swelling",
    "irregular heartbeats and palpitations",
    "chest pain, especially when I exert myself",
    "spread to my left arm and jaw",
    "Raynaud's syndrome",
    "my heart is racing or skipping beats",
    "taking Norco (acetaminophen / hydrocodone)",
    "muscle spasms in my back",
    "anxious",
    "waking up in the middle of the night with severe back pain",
    "urine is darker than usual",
    "not been vaccinated against meningitis",
    "bowed legs",
    "bone pain",
    "vitamin D and calcium",
    "legs have been aching",
    "still experiencing breakthrough attacks",
    "short of breath",
    "puffy ankles",
    "blood clot in my leg"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines, and the decision-qualifying patient facts: acuity and timing (acute vs chronic vs breakthrough), severity, prior therapy and response, age group, pregnancy, organ function, vaccination status, and any explicit doctor statement about treatment preference or safety. Record these as exact dialogue excerpts so they can be weighed, and do not record a fact that is not stated.",
    "safety_check": "Check patient-specific contraindications and drug interactions using only stated facts. When a class-level risk is named, identify the subclass or property that carries the risk and avoid excluding safe members of the class. Treat CNS depressant stacking, vasospastic interactions, and vaccination-status requirements as clinically meaningful signals only when the dialogue states the relevant patient fact.",
    "option_selection": "Choose the option that best satisfies the indication, the clinical qualifier, the time course/line of therapy, the care setting, and patient-specific safety. Prefer the option whose labeled use matches the stated severity and setting, and when a doctor preference is explicitly stated, use that as the decisive comparator after confirming indication and safety."
  }
}

{
  "diagnosis": "Recurring failures come from three generalizable causes: (1) option_selection prefers the more familiar or dialogue-mentioned drug over the option with better indication fit for the stated condition, even when the other option is less appropriate or less safe; (2) safety_check treats an unmentioned interaction or contraindication as if it were established and either withholds an appropriate drug or invents risk, rather than resolving only stated facts; (3) patient_evidence frequently misses key stated constraints such as current medication use, symptom timing, pregnancy history, or activity/exposure history because it does not force retrieval of exact patient statements. Prior evidence also overstates distinctions that are not explicit in the dialogue. These are mechanism-level causes, not case answers.",
  "skills": [
    {
      "id": "indication_first_selection",
      "text": "When selecting a medication, first map the stated diagnosis or syndrome to the option whose mechanism and indication most directly treat that condition. Do not let a drug that is merely named in the dialogue, or that is more familiar, override a better-indicated option unless the dialogue establishes a patient-specific reason to avoid it."
    },
    {
      "id": "explicit_constraint_resolution",
      "text": "Before excluding an appropriate option, require an explicit stated contraindication, allergy, or interaction. If the patient fact is missing, do not invent it; if a potential concern is only hypothesized by the clinician, treat it as a prompt for monitoring rather than as a confirmed reason to choose a worse-indicated drug."
    },
    {
      "id": "retrieve_exact_patient_facts",
      "text": "Extract exact patient statements for current medicines, symptom duration and triggers, pregnancy or gestational history, recent travel or exposure, and prior diagnoses. Use these excerpts to constrain both indication and safety rather than relying on general impressions."
    },
    {
      "id": "compare_within_class",
      "text": "When multiple options belong to the same class or related mechanism, compare them by formulation, indication, route, and patient-specific interaction profile. Do not assume that two similar drugs are interchangeable; choose the one that best matches the stated clinical problem and avoids the stated risks."
    },
    {
      "id": "avoid_reference_position_bias",
      "text": "Do not encode or use benchmark-position, answer-letter, or case-specific shortcuts. Generalize from the mechanism of action, labeled indication, and stated patient facts only."
    }
  ],
  "focus_terms": [
    "I'm currently taking",
    "I've been taking",
    "diagnosed with",
    "history of",
    "during my last pregnancy",
    "I visited",
    "exposure to",
    "started about",
    "come and go",
    "after physical activities",
    "before my workout",
    "I use an inhaler",
    "family history of",
    "currently under control",
    "seem to worsen when",
    "more often when I take"
  ],
  "modules": {
    "patient_evidence": "Extract exact dialogue statements about the stated condition, current medicines, symptom onset and triggers, pregnancy/gestational history, recent travel or environmental exposure, allergies, and relevant family history. Preserve the patient's wording as evidence, and do not infer absent facts.",
    "safety_check": "Only use explicitly stated contraindications, allergies, or interactions. If the dialogue does not establish a safety problem, do not treat the option as unsafe. When a possible interaction is raised but not confirmed, note it as a monitoring issue rather than a reason to eliminate an otherwise indicated option.",
    "option_selection": "Rank options by fit to the stated diagnosis and patient-specific facts. Prefer the option whose indication and mechanism most directly address the active problem, unless an explicit stated contraindication or interaction rules it out. Do not select based on dialogue mention, familiarity, or benchmark position."
  }
}
